int inode_permission(struct inode *inode, int mask)
{
  int retval;

  if (mask & MAY_WRITE) {
    umode_t mode = inode->i_mode;
    if (IS_RDONLY(inode) &&
      (S_ISREG(mode) || S_ISDIR(mode) || S_ISLNK(mode)))
      return -EROFS;
  }

  if (inode->i_op->permission)
    retval = inode->i_op->permission(inode, mask);
  else
    retval = generic_permission(inode, mask, NULL);
  if (retval)
    return retval;

  return security_inode_permission(inode, mask, nd);
}

int get_unused_fd_flags(unsigned flags)
{
  struct files_struct *files = current->files;
  int fd, error;

  error = expand_files(files, 0);
  if (error < 0)
    return error;

  fd = find_next_zero_bit(files->fdt->open_fds->fds_bits,
    files->fdt->max_fds, files->next_fd);

  FD_SET(fd, files->fdt->open_fds);
  FD_CLR(fd, files->fdt->close_on_exec);
  files->next_fd = fd + 1;
  return fd;
}

struct file *nameidata_to_filp(struct nameidata *nd)
{
  const struct cred *cred = current_cred();
  struct file *filp;

  filp = dentry_open(nd->path.dentry, nd->path.mnt, nd->intent.open.flags, cred);
  if (!IS_ERR(filp)) {
    /* This gets set unconditionally for now */
    filp->f_pos = 0;
  }
  return filp;
}

void fd_install(unsigned int fd, struct file *file)
{
  struct files_struct *files = current->files;
  struct fdtable *fdt;

  spin_lock(&files->file_lock);
  fdt = files_fdtable(files);
  BUG_ON(fdt->fd[fd] != NULL);
  rcu_assign_pointer(fdt->fd[fd], file);
  spin_unlock(&files->file_lock);
}

